function G({registerIndicator:F,sourceValues:H,nulls:T}){F({id:"oa-mstoch",name:"Ehlers MESA Stochastic (MSTOCH)",category:"Oscillators",placement:"pane",inputs:[{key:"stochLength",type:"number",label:"Stochastic Length",default:20,min:2,max:500,step:1},{key:"hpLength",type:"number",label:"HP Length",default:48,min:1,max:5e3,step:1,tooltip:"Highpass cutoff period: removes cycles longer than this."},{key:"ssLength",type:"number",label:"SS Length",default:10,min:1,max:5e3,step:1,tooltip:"Super Smoother cutoff period: removes cycles shorter than this."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"mstoch",type:"line",title:"MSTOCH",style:{color:"#ffeb3b",lineWidth:2}}],levels:()=>[{price:.8,title:"Overbought",color:"#787b86",dashed:!0},{price:.5,title:"Midline",color:"#787b86",dashed:!0},{price:.2,title:"Oversold",color:"#787b86",dashed:!0}],calc(y,n){const I=Math.max(2,Math.min(500,Math.floor(Number(n.stochLength)||20))),q=Math.max(1,Math.floor(Number(n.hpLength)||48)),Q=Math.max(1,Math.floor(Number(n.ssLength)||10)),p=H(y,n.source??"close"),o=y.length,g=Math.sqrt(2)*Math.PI,d=g/q,m=Math.exp(-d),v=2*m*Math.cos(d),N=-m*m,R=(1+v-N)/4,x=g/Q,u=Math.exp(-x),f=2*u*Math.cos(x),M=-u*u,L=1-f-M,s=new Array(o).fill(0),e=new Array(o).fill(0),c=new Array(o).fill(0),r=new Array(o).fill(0),S=new Array(o).fill(NaN);for(let t=0;t<o;t++){const C=p[t],l=t>=1?p[t-1]:NaN,P=t>=2?p[t-2]:NaN,A=Number.isFinite(C)?C:Number.isFinite(l)?l:0,w=Number.isFinite(l)?l:A,V=Number.isFinite(P)?P:w,W=t>=1?s[t-1]:0,_=t>=2?s[t-2]:0;s[t]=R*(A-2*w+V)+v*W+N*_;const k=t>=1?s[t-1]:s[t],j=t>=1?e[t-1]:s[t],z=t>=2?e[t-2]:k;e[t]=L*(s[t]+k)/2+f*j+M*z;let b=e[t],h=e[t];for(let a=1;a<=I-1;a++){const i=t-a>=0?e[t-a]:e[t];i>b&&(b=i),i<h&&(h=i)}const O=b-h;c[t]=O>0?(e[t]-h)/O:.5;const E=t>=1?c[t-1]:c[t],B=t>=1?r[t-1]:c[t],D=t>=2?r[t-2]:E;r[t]=L*(c[t]+E)/2+f*B+M*D,S[t]=Math.max(0,Math.min(1,r[t]))}return{mstoch:T(S)}}})}export{G as default};
